import{_ as s,H as n,f as i,i as e}from"./chunks/framework.BH2BK_3i.js";const k=JSON.parse('{"title":"01 | 源起：动态编程语言如何引爆虚拟机的革命？","description":"","frontmatter":{},"headers":[{"level":2,"title":"编程语言的发展","slug":"编程语言的发展","link":"#编程语言的发展","children":[]},{"level":2,"title":"编程语言虚拟机","slug":"编程语言虚拟机","link":"#编程语言虚拟机","children":[{"level":3,"title":"屏蔽硬件差异","slug":"屏蔽硬件差异","link":"#屏蔽硬件差异","children":[]},{"level":3,"title":"自动内存管理","slug":"自动内存管理","link":"#自动内存管理","children":[]},{"level":3,"title":"编译和执行","slug":"编译和执行","link":"#编译和执行","children":[]}]},{"level":2,"title":"Python 的策略","slug":"python-的策略","link":"#python-的策略","children":[]},{"level":2,"title":"我们的策略","slug":"我们的策略","link":"#我们的策略","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"手写Python虚拟机/01｜源起：动态编程语言如何引爆虚拟机的革命？.md","filePath":"手写Python虚拟机/01｜源起：动态编程语言如何引爆虚拟机的革命？.md","lastUpdated":1795557449000}'),t={name:"手写Python虚拟机/01｜源起：动态编程语言如何引爆虚拟机的革命？.md"};function p(l,a,h,o,r,c){return n(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="_01-源起-动态编程语言如何引爆虚拟机的革命" tabindex="-1">01 | 源起：动态编程语言如何引爆虚拟机的革命？ <a class="header-anchor" href="#_01-源起-动态编程语言如何引爆虚拟机的革命" aria-label="Permalink to &quot;01 | 源起：动态编程语言如何引爆虚拟机的革命？&quot;">​</a></h1><p>你好，我是海纳。欢迎你加入学习，迈出从零开始实现 Python 虚拟机的第一步。</p><p>在正式开始之前，我想先带你回顾一下编程语言的发展历史，在这个过程中你会看到编程语言虚拟机是如何产生的，它为了填补静态语言的缺陷演化出了哪些能力，还有不同编程语言的实现策略。学完了这节课的内容你就能回答“虚拟机从哪儿来”这个问题了。</p><h2 id="编程语言的发展" tabindex="-1">编程语言的发展 <a class="header-anchor" href="#编程语言的发展" aria-label="Permalink to &quot;编程语言的发展&quot;">​</a></h2><p>计算机技术发展到今天，诞生了很多编程语言，这些语言的工作原理各不相同。根据它们与硬件平台的远近关系，我们可以把编程语言粗略地划分为以汇编为代表的底层语言和以 C++、Java 为代表的高级语言。</p><p>汇编语言的特点是直接与硬件平台提供的寄存器、内存、IO 端口打交道，能力十分强大，所以早期操作系统镜像的加载和初始化经常会使用汇编语言来实现；语言助记符（例如 mov、add）几乎与 CPU 指令一一对应，使用汇编语言基本不需要考虑编译器的影响，这就让编程人员对代码有绝对的控制权。但是汇编语言因为太接近底层，这就使得其表达能力不强，开发效率低。</p><p>为了提高应用程序的开发效率，人们发明了高级语言。C 语言是非常重要的一个语言，它保留了内嵌汇编，并且可以通过链接器将汇编语言开发的模块与 C 语言开发的模块链接在一起；同时 C 语言的指针也保留了汇编语言中内存操作的逻辑。它是一门承上启下的语言，大多数操作系统都是用 C 语言开发的，说 C 语言是计算机行业的基石也不过分。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E5%86%99Python%E8%99%9A%E6%8B%9F%E6%9C%BA/images/01/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E5%86%99Python%E8%99%9A%E6%8B%9F%E6%9C%BA/images/01/1.png" alt=""></a></p><p>后来，随着应用软件的规模越来越大，面向对象的编程思想开始流行。面向对象的语言也应运而生，典型代表就是 C++。面向对象的编程方式可以让开发者们以模块化、对象化的思想进行设计和开发，大大提高了编程语言的抽象能力。到目前为止，面向对象的编程方式仍然是当今世界的主流。</p><p>C++ 语言虽然开发速度很快，运行性能也好，但仍然有两个主要的痛点。</p><p>第一个是内存管理，使用 C++ 的时候，编程人员要十分小心地使用内存，因为稍不注意就容易引起内存泄漏，比如下面我给出的这个示例。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">void foo() {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> Data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> new </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> //</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">…</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> //</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">many other codes</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (some_condition())</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> //</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> //</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">many other codes</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> delete</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>在 some_condition 条件满足的情况下，foo 方法就直接返回了，漏掉了 delete 语句。这一块内存没有被释放，但却没有任何变量引用它了。也就是说，应用程序再也无法正常访问这块内存了。这就是内存泄漏。</p><p>如果函数体比较小，逻辑相对简单，一般不会犯这种错误，但如果逻辑比较复杂，尤其是多人多版本维护同一份代码的情况下，自己添加的 return 逻辑将别人添加的 delete 跳过去就非常常见了。</p><p>第二个痛点就是跨平台。当前主流的体系结构是 x86 和 Arm，操作系统包括 Windows、Linux、Android 等等，跨平台是指同一份代码可以在多种不同的体系结构和操作系统上正确执行。</p><p>C/C++ 这类语言是静态编译的，它们编译生成的是可执行程序，例如 Windows 系统上的.exe文件，可执行程序中代码段里的内容是与平台直接相关的，在 x86 系统上，就会产生 x86 的机器指令，在 Arm 系统上，就会产生 Arm 的机器指令。</p><p>另外，还要考虑编译器、操作系统以及运行时库的影响。</p><p>同样的 C++ 代码，不同版本的编译器和操作系统会产生不同的机器指令，同时应用程序所依赖的动态链接库也会有不兼容的情况。静态编译为应用程序的分发和部署带来了困难。</p><h2 id="编程语言虚拟机" tabindex="-1">编程语言虚拟机 <a class="header-anchor" href="#编程语言虚拟机" aria-label="Permalink to &quot;编程语言虚拟机&quot;">​</a></h2><p>为了解决这些问题，编程语言虚拟机就应运而生了，它要解决的问题主要是屏蔽硬件差异和自动内存管理，在这个基础上，又发展出了即时编译等新的特性。</p><h3 id="屏蔽硬件差异" tabindex="-1">屏蔽硬件差异 <a class="header-anchor" href="#屏蔽硬件差异" aria-label="Permalink to &quot;屏蔽硬件差异&quot;">​</a></h3><p>编程语言虚拟机的一个重要能力就是屏蔽硬件差异。以 Java 为例，Java 源代码文件会被javac 先编译生成 class 文件，多个 class 文件可以集中在一起，生成一个 jar 文件。</p><p>通常，一个模块会压缩成一个 jar 文件，而应用程序就以 jar 包的方式分发和部署。class 文件的格式是固定的，它的代码段里全部是 Java 字节码。不管在什么硬件环境下，相同的字节码得到的执行结果一定是相同的。</p><p>字节码的设计非常类似于 CPU 指令，它有自己定义的数值计算、位操作、比较操作、跳转操作等。所以人们把这种专门为某一类编程语言所开发的字节码以及其解释器合并称为编程语言虚拟机。</p><p>我们可以借助一个例子来了解 Java 虚拟机的工作原理，你可以看一下我给出的 Java 代码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void foo() {</span></span>
<span class="line"><span> int a = 2;</span></span>
<span class="line"><span> int b = 3;</span></span>
<span class="line"><span> int c = a + b;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>它编译的 Java 字节码如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0: iconst_2</span></span>
<span class="line"><span>1: istore_1</span></span>
<span class="line"><span>2: iconst_3</span></span>
<span class="line"><span>3: istore_2</span></span>
<span class="line"><span>4: iload_1</span></span>
<span class="line"><span>5: iload_2</span></span>
<span class="line"><span>6: iadd</span></span>
<span class="line"><span>7: istore_3</span></span>
<span class="line"><span>8: return</span></span></code></pre></div><p>我们可以使用下图来描述这个字节码的执行过程。Java 的执行过程可以通过高级数据结构的栈来实现，而不必关心 CPU 的具体体系结构。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E5%86%99Python%E8%99%9A%E6%8B%9F%E6%9C%BA/images/01/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E5%86%99Python%E8%99%9A%E6%8B%9F%E6%9C%BA/images/01/2.png" alt=""></a></p><p>对字节码文件进行加载、分析、执行的逻辑都在 Java 语言虚拟机里封装了。在不同的硬件平台和不同的操作系统上，Java 语言虚拟机的实现各不相同，但是它提供的字节码执行器的功能是完全相同的。Java 早期推广的时候，曾经以“write once, run everywhere”作为重要的特性进行宣传，指的主要就是 Java 语言虚拟机屏蔽硬件差异的能力。</p><h3 id="自动内存管理" tabindex="-1">自动内存管理 <a class="header-anchor" href="#自动内存管理" aria-label="Permalink to &quot;自动内存管理&quot;">​</a></h3><p>使用 C++ 进行开发时，开发人员要十分注意内存的使用，避免不合理的内存分配和内存泄漏问题。如果能够自动地回收和整理不被引用的内存，就可以彻底避免内存泄漏了，这就是垃圾回收机制。</p><p>编程语言自动内存管理的研究开始得比较早，在当今主流的带有垃圾回收的编程语言（例如Java、Python、Ruby、Go）被开发出来之前，垃圾回收的算法就已经非常成熟了。</p><p>大体上，垃圾回收可以分为引用计数和 Tracing GC 两大类，其中引用计数的代表就是CPython，也就是我们平常最常使用的社区版 Python。而大多数编程语言虚拟机基本上都使用 Tracing GC。Tracing GC 的家族非常庞大，在这里我们不展开讨论了。在后面自动内存管理那部分，我们会继续深入地讨论这个问题。</p><h3 id="编译和执行" tabindex="-1">编译和执行 <a class="header-anchor" href="#编译和执行" aria-label="Permalink to &quot;编译和执行&quot;">​</a></h3><p>在讲解屏蔽硬件差异的时候，我举了 Java 字节码的例子。但其实编程语言还可以有更多的实现，我们选择几个代表来看一下。</p><p>第一类是以 Java 为代表的有字节码的虚拟机，前边已经介绍过了，这里不再详细介绍了。</p><p>第二类是以 V8 为代表的 JavaScript 虚拟机。V8 是谷歌公司开发的，用于执行 JavaScript 的虚拟机，Chrome 里的 JS 都是由 V8 解释执行的。</p><p>众所周知，网页上的 JS 代码都是以源代码的形式由服务端发送到客户端，然后客户端来执行的。相比 Java 的执行过程，这一过程中缺少了编译生成字节码的步骤。</p><p>实际上 V8 是比较特殊的，它根本不需要生成字节码，而是直接将源代码翻译成树形结构，我们称之为抽象语法树。然后，V8 的执行器就通过后序遍历这棵树，在访问语法树上的不同结点时，执行与这个结点相对应的动作，最终完成代码的解释执行。这种做法是把源代码的编译和程序的执行直接绑定在一起。</p><p>第三类是以 Go 为代表的静态编译的类型。如果对 Go 语言的源代码进行编译的话，你会发现，即使是很小的一段代码，编译的可执行程序的体积也会很大，这是因为 Go 在编译的时候直接将虚拟机与用户代码链接在了一起。</p><p>这种直接静态编译的好处是，既能通过虚拟机实现对硬件平台和操作系统的屏蔽，又能提供很好的执行效率。</p><p>可见，在编译策略和执行器的选择上，编程语言的实现是有多种选择的。没有哪一种选择是十全十美的，只能根据编程语言所面临的场景以及它所要解决的问题来具体决策。</p><h2 id="python-的策略" tabindex="-1">Python 的策略 <a class="header-anchor" href="#python-的策略" aria-label="Permalink to &quot;Python 的策略&quot;">​</a></h2><p>Python 比较灵活，一方面它规定了自己的字节码，但它又不要求程序必须以字节码文件（.pyc）来发布。它完全支持甚至鼓励应用程序以源代码的方式发行。</p><p>本质上，在 Python 虚拟机内部，源代码也是先编译成字节码然后再执行的，也就是说Python 的编译器 Python 虚拟机的一部分，它不像 Java 虚拟机，javac 用于编译，和执行是分离的。你可以回忆一下 Python 中的 eval 功能，其实 eval 就是调用了 Python 内置的编译器，来编译字符串。</p><p>当然 Python 虚拟机也有其他的开源实现，例如，Jython 是一种用 Java 实现的 Python 语言，它的原理与 CPython 大有不同，它放弃了 Python 的原生字节码，直接将 py 源代码文件翻译成了由 Java 字节码组成的 class 文件。而我们知道，class 文件是可以直接在 Java 虚拟机上执行的，这样一来，Python 代码就可以自由地使用各种强大的 Java 类库。通过编译，Jython 实现了 Python 与 Java 的无缝衔接。</p><h2 id="我们的策略" tabindex="-1">我们的策略 <a class="header-anchor" href="#我们的策略" aria-label="Permalink to &quot;我们的策略&quot;">​</a></h2><p>我们课程的定位是从零开始实现 Python 语言，所以内容上包括从源码编译到字节码文件、虚拟机加载执行、运行时库、内存管理等模块。</p><p>我们将采用 C++ 作为基础的开发语言来实现编译器，而不是 C 语言或者 Java，主要是考虑到相比 C 语言，C++ 的表达能力更强，开发速度更快。相比 Java，C++ 直接操作内存的能力更强，对整个程序的内存使用有更好、更精细地掌握，这是我们开发一个内存管理系统的必要条件。</p><p>我所用的平台是 x86 64 位的 ubuntu，你完全可以使用其他体系结构的其他操作系统来进行实验。因为我们的代码使用了 CMake 来进行管理，所以即使你使用 Windows 系统或者 macOS都没有太大的问题。</p><p>C++ 的编译器可以使用 GCC，也可以使用 LLVM，这对我们的项目没有影响。你可以选用自己习惯的开发工具，VSCode、JetBrain 或者 VIM 都可以，这些工具对代码的实现也没什么特别的影响。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这节课我们介绍了几种不同的编程语言的对比，并且通过示例说明了高级语言采用语言虚拟机的核心原因。语言虚拟机带来了三个明显的优势。</p><ol><li><p>虚拟机可以屏蔽硬件差异，实现了一次构建，多处运行的能力。</p></li><li><p>虚拟机可以自动管理内存，将程序员从内存泄漏、空指针、重复释放等问题里解放出来，更多地将精力聚焦到业务逻辑上。</p></li><li><p>支持语言的动态特性，例如运行时修改类定义、反射等。</p></li></ol><p>最后，我们决定使用 CMake 和 C++ 来构建语言虚拟机。下一节课我们就开始着手构建项目了。</p><p>注：点击链接查看课程代码地址</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>TIOBE 是编程语言的热度排行榜，请你说一说排行榜前十名的编程语言，哪些是静态编译语言，哪些是依赖虚拟机的动态语言？欢迎你把你的答案分享到评论区，也欢迎你把这节课的内容分享给其他朋友，我们下节课再见！</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E5%86%99Python%E8%99%9A%E6%8B%9F%E6%9C%BA/images/01/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E5%86%99Python%E8%99%9A%E6%8B%9F%E6%9C%BA/images/01/3.png" alt=""></a></p>`,61)])])}const g=s(t,[["render",p]]);export{k as __pageData,g as default};
